// History.jsx

import React from "react";
import { useDispatch, useSelector } from "react-redux"; // Import hooks from react-redux
import { addHistoryItem, clearHistory } from "e"; // Import actions

const History = () => {
  const dispatch = useDispatch(); // Used to dispatch actions
  const history = useSelector((state) => state.history.history); // Get the current history from Redux store

  const handleAddToHistory = () => {
    dispatch(addHistoryItem("New history item")); // Dispatch action to add new item to history
  };

  const handleClearHistory = () => {
    dispatch(clearHistory()); // Dispatch action to clear all history items
  };

  return (
    <div>
      <h3>History</h3>
      <ul>
        {history.map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
      <button onClick={handleAddToHistory}>Add New Item</button>
      <button onClick={handleClearHistory}>Clear History</button>
    </div>
  );
};

export default History;
